CREATE DATABASE IF NOT EXISTS catalog; USE catalog; CREATE TABLE IF NOT EXISTS products (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(255), description VARCHAR(255)); CREATE TABLE IF NOT EXISTS ssh_credentials (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(255), password VARCHAR(255)); CREATE USER IF NOT EXISTS 'appuser'@'%' IDENTIFIED BY 'apppass'; GRANT SELECT ON catalog.* TO 'appuser'@'%'; FLUSH PRIVILEGES;